useEffect(()=>{game.current?.setInterior(storeOpen?'gun':bikeShopOpen?'bike':hospitalOpen?'hospital':venueOpen&&adultOk?venueOpen:null);},[storeOpen,bikeShopOpen,hospitalOpen,venueOpen,adultOk,gameGen]);
