async function enter(action:'create'|'join',mode:GameMode='city'){setPending(true);setError('');try{const response=await fetch('/api/room',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,name:name.trim()||'Khách qua phố',world:WORLD_VERSION,zv:ZOMBIE_VERSION,...(action==='join'?{code}:{mode})}),signal:AbortSignal.timeout(12000)});const data=await response.json() as Partial<RoomJoined>&{error?:string;room:string;id:string;token:string;peers:PeerState[]};if(!response.ok)throw new Error(data.error||'Chưa thể vào phòng. Hãy thử lại.');const roomMode:GameMode=data.mode==='zombie'?'zombie':'city';modeGen.current++;game.current?.setRoom({mode:roomMode,selfId:data.id,slot:data.slot??0,host:data.host??null,epoch:data.epoch??0,ff:!!data.ff,name:name.trim()||'Khách qua phố',color:data.color});game.current?.reset(roomMode);game.current?.setActive(true);if(action==='join'&&roomMode==='zombie')setTimeout(()=>setDistrictBanner({key:++bannerCount.current,zone:false,eyebrow:`Phòng ${data.room}`,title:'Đang chơi chế độ Zombie',subtitle:'Cùng sống sót qua từng đợt'}),400);setSession({room:data.room,id:data.id,token:data.token});setActive(true);if(areaRef.current)showBanner(areaRef.current,false);setPeers(data.peers||[]);}catch(e){setError(e instanceof Error?e.message:'Không thể kết nối máy chủ.');}finally{setPending(false);}}
